def copy_single_files(apps, schema_editor):
    """Each Document's single file (Document.arquivo) becomes its first
    DocumentFile: the same stored file, nothing is copied on disk."""
    Document = apps.get_model("django_resaas", "Document")
    DocumentFile = apps.get_model("django_resaas", "DocumentFile")
    rows = []
    for document in Document.objects.exclude(arquivo="").exclude(arquivo__isnull=True).iterator():
        rows.append(DocumentFile(
            document_id=document.id,
            arquivo=document.arquivo.name,
            name=document.arquivo.name.rsplit("/", 1)[-1],
            state="Active",
            created_by_id=document.created_by_id,
            updated_by_id=document.updated_by_id,
        ))
    DocumentFile.objects.bulk_create(rows, batch_size=500)


